17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Map;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.server.ResponseStatusException;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        owner.setAddress(normalizeAddress(owner.getAddress()));
117	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
118	        if (effectiveRegistrationDate == null) {
119	            effectiveRegistrationDate = LocalDate.now();
120	        }
121	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
122	        owner.setRegistrationDate(effectiveRegistrationDate);
123	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
124	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
125	                "the maximum number of owners that may be created today has been reached");
126	        }
127	        if (isTelephoneInUse(normalizedTelephone, null)) {
128	            throw new ResponseStatusException(HttpStatus.CONFLICT,
129	                "telephone is already in use by another owner");
130	        }
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        if (!sharesHousehold
133	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                "another owner with the same last name already lives at this address");
136	        }
137	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
138	            throw new ResponseStatusException(HttpStatus.CONFLICT,
139	                "city has reached its maximum number of owners");
140	        }
141	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
142	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
143	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        owner.setBulkSignupWarning(
145	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
146	        if (sharesHousehold) {
147	            this.clinicService.assignHousehold(owner);
148	        }
149	        this.clinicService.saveOwner(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
152	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
153	            ownerDto.getMembershipLevel());
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
163	        if (currentOwner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        currentOwner.setAddress(ownerFieldsDto.getAddress());
167	        currentOwner.setCity(ownerFieldsDto.getCity());
168	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	        currentOwner.setLastName(ownerFieldsDto.getLastName());
170	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
171	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
172	        this.clinicService.saveOwner(currentOwner);
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Transactional
178	    @Override
179	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        this.clinicService.deleteOwner(owner);
185	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        HttpHeaders headers = new HttpHeaders();
196	        Pet pet = petMapper.toPet(petFieldsDto);
197	        owner.setId(ownerId);
198	        pet.setOwner(owner);
199	        pet.getType().setName(null);
200	        this.clinicService.savePet(pet);
201	        PetDto petDto = petMapper.toPetDto(pet);
202	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
203	            .buildAndExpand(pet.getId()).toUri());
204	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner != null) {
212	            Pet currentPet = this.clinicService.findPetById(petId);
213	            if (currentPet != null) {
214	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
215	                currentPet.setName(petFieldsDto.getName());
216	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
217	                this.clinicService.savePet(currentPet);
218	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
227	        HttpHeaders headers = new HttpHeaders();
228	        Visit visit = visitMapper.toVisit(visitFieldsDto);
229	        Pet pet = new Pet();
230	        pet.setId(petId);
231	        visit.setPet(pet);
232	        this.clinicService.saveVisit(visit);
233	        VisitDto visitDto = visitMapper.toVisitDto(visit);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
235	            .buildAndExpand(visit.getId()).toUri());
236	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
237	    }
238	
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
243	        Owner owner = this.clinicService.findOwnerById(ownerId);
244	        if (owner != null) {
245	            Pet pet = owner.getPet(petId);
246	            if (pet != null) {
247	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    /**
254	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
255	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
256	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
257	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
258	     *
259	     * @param city     the owner's city
260	     * @param lastName the owner's last name
261	     * @return the assigned customer code
262	     */
263	    private String nextCustomerCode(String city, String lastName) {
264	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
265	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
266	        int sequence = countOwnersInCity(city) + 1;
267	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
268	    }
269	
270	    /**
271	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
272	     * owner's city already contains this many owners.
273	     */
274	    private static final int CITY_CAPACITY = 50;
275	
276	    /**
277	     * The maximum number of owners that may be created on a single day. A create is rejected with
278	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
279	     * {@code registrationDate}.
280	     */
281	    private static final int DAILY_CREATE_LIMIT = 100;
282	
283	    /**
284	     * The number of owners that must already have been created for the current day before a new
285	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
286	     * owners already carry today's {@code registrationDate}.
287	     */
288	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
289	
290	    /**
291	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
292	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
293	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
294	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
295	     * falls on a business day.
296	     *
297	     * @param date the effective registration date
298	     * @return the same date when it is a weekday, otherwise the following Monday
299	     */
300	    private static LocalDate rollToBusinessDay(LocalDate date) {
301	        return switch (date.getDayOfWeek()) {
302	            case SATURDAY -> date.plusDays(2);
303	            case SUNDAY -> date.plusDays(1);
304	            default -> date;
305	        };
306	    }
307	
308	    /**
309	     * Counts the existing owners whose {@code registrationDate} equals the given (already
310	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
311	     * business day. Called before a new owner is saved, so the returned value reflects the number of
312	     * owners created for that day prior to this create.
313	     *
314	     * @param date the adjusted business-day registration date to count against
315	     * @return the number of existing owners registered on that date
316	     */
317	    private int countOwnersRegisteredOn(LocalDate date) {
318	        return (int) this.clinicService.findAllOwners().stream()
319	            .filter(existing -> date.equals(existing.getRegistrationDate()))
320	            .count();
321	    }
322	
323	    /**
324	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
325	     *
326	     * @param city the city to count owners for
327	     * @return the number of existing owners in that city
328	     */
329	    private int countOwnersInCity(String city) {
330	        return (int) this.clinicService.findAllOwners().stream()
331	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
332	            .count();
333	    }
334	
335	    /**
336	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
337	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
338	     *
339	     * @param customerCode     the owner's assigned customer code
340	     * @param registrationDate the owner's registration date
341	     * @return the assigned membership number
342	     */
343	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
344	        String yy = String.format("%02d", registrationDate.getYear() % 100);
345	        return String.format("%s-M%s", customerCode, yy);
346	    }
347	
348	    /**
349	     * Counts the existing owners that already share the given first name and last name, comparing
350	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
351	     * the number of namesakes that existed prior to this create.
352	     *
353	     * @param firstName the new owner's first name
354	     * @param lastName  the new owner's last name
355	     * @return the number of existing owners with the same first and last name
356	     */
357	    private int countNamesakes(String firstName, String lastName) {
358	        int count = 0;
359	        for (Owner existing : this.clinicService.findAllOwners()) {
360	            if (firstName.equalsIgnoreCase(existing.getFirstName())
361	                && lastName.equalsIgnoreCase(existing.getLastName())) {
362	                count++;
363	            }
364	        }
365	        return count;
366	    }
367	
368	    /**
369	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
370	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
371	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
372	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
373	     * string is what gets stored and returned.
374	     *
375	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
376	     *
377	     * @param telephone the raw telephone value supplied by the client
378	     * @return the normalized E.164 telephone number
379	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
380	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
381	     *                                 digits after the {@code '+'})
382	     */
383	    private static String normalizeTelephone(String telephone) {
384	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
385	        String digits;
386	        if (cleaned.startsWith("+")) {
387	            digits = cleaned.substring(1);
388	        } else {
389	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
390	            digits = "61" + national;
391	        }
392	        if (!digits.matches("[0-9]{8,15}")) {
393	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
394	                "telephone could not be normalized to a valid E.164 number");
395	        }
396	        return "+" + digits;
397	    }
398	
399	    /**
400	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
401	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
402	     *
403	     * @param telephone the stored telephone value, possibly {@code null}
404	     * @return the E.164 form, or the raw value when it cannot be normalized
405	     */
406	    private static String toComparableTelephone(String telephone) {
407	        try {
408	            return normalizeTelephone(telephone);
409	        } catch (ResponseStatusException ex) {
410	            return telephone;
411	        }
412	    }
413	
414	    /**
415	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
416	     * containing at least one dot, none of the three sections containing whitespace or an
417	     * additional {@code @}.
418	     */
419	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
420	
421	    /**
422	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
423	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
424	     * value is then stored and returned lower-cased.
425	     *
426	     * @param email the raw email value supplied by the client, possibly {@code null}
427	     * @return the lower-cased email, or {@code null} when none was supplied
428	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
429	     *                                 is not a syntactically valid address
430	     */
431	    private static String normalizeEmail(String email) {
432	        if (email == null) {
433	            return null;
434	        }
435	        if (!EMAIL_PATTERN.matcher(email).matches()) {
436	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
437	                "email must be a syntactically valid address");
438	        }
439	        return email.toLowerCase(Locale.ROOT);
440	    }
441	
442	    /**
443	     * Common street-type abbreviations expanded to their full word during address normalization.
444	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
445	     */
446	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
447	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
448	
449	    /**
450	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
451	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
452	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
453	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
454	     * address comparison (household duplicate detection and the shared household id).
455	     *
456	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
457	     *
458	     * @param address the raw address supplied by the client, possibly {@code null}
459	     * @return the normalized address
460	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
461	     *                                 after normalization (required field)
462	     */
463	    private static String normalizeAddress(String address) {
464	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
465	        if (collapsed.isEmpty()) {
466	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
467	                "address must not be blank");
468	        }
469	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
470	        StringBuilder normalized = new StringBuilder();
471	        for (int i = 0; i < tokens.length; i++) {
472	            if (i > 0) {
473	                normalized.append(' ');
474	            }
475	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
476	        }
477	        return normalized.toString();
478	    }
479	
480	    /**
481	     * Determines whether the given normalized E.164 telephone is already used by any owner other
482	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
483	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
484	     * inputs representing the same number are treated as duplicates.
485	     *
486	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
487	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
488	     * @return {@code true} if another owner already uses the telephone
489	     */
490	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
491	        for (Owner existing : this.clinicService.findAllOwners()) {
492	            if (excludeId != null && excludeId.equals(existing.getId())) {
493	                continue;
494	            }
495	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
496	                return true;
497	            }
498	        }
499	        return false;
500	    }
501	
502	}
